<?php require '../config/config.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){
  $id=(int)($_POST['id']??0); $action=$_POST['action']??'';
  if($action==='update'){
    $status=$_POST['status']??'open'; $note=trim($_POST['admin_note']??'');
    if(in_array($status,['open','in_progress','resolved','closed'],true)){$pdo->prepare('UPDATE support_requests SET status=?,admin_note=? WHERE id=?')->execute([$status,$note?:null,$id]);flash('success','Support request updated.');}
  } elseif($action==='delete'){$pdo->prepare('DELETE FROM support_requests WHERE id=?')->execute([$id]);flash('success','Support request deleted.');}
  header('Location: support.php');exit;
}
$rows=$pdo->query('SELECT sr.*,u.name,u.email,u.phone FROM support_requests sr LEFT JOIN users u ON u.id=sr.user_id ORDER BY sr.created_at DESC')->fetchAll();
$title='Support Requests'; require '../includes/header.php'; ?>
