<section class="section"><div class="container"><h1>Support Requests</h1><p class="muted">Only administrators can manage requests. Members can submit requests and view open community requests.</p><div class="tablewrap"><table class="table"><thead><tr><th>Member</th><th>Request</th><th>Category</th><th>Status</th><th>Admin Note</th><th>Action</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6" class="empty">No support requests.</td></tr><?php endif; ?><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['name']?:'Deleted member')?></strong><br><span class="muted smalltext"><?=e($r['email']??'')?></span></td><td><strong><?=e($r['title'])?></strong><br><?=nl2br(e($r['description']))?></td><td><?=e($r['category'])?></td><td><span class="status <?=e($r['status'])?>"><?=e(str_replace('_',' ',ucfirst($r['status'])))?></span></td><td><?=e($r['admin_note']?:'—')?></td><td><details><summary class="mini-btn">Manage</summary><form method="post" class="reset-form" style="position:relative;top:auto;right:auto;width:260px"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=e($r['id'])?>"><label>Status</label><select name="status"><option value="open" <?=$r['status']==='open'?'selected':''?>>Open</option><option value="in_progress" <?=$r['status']==='in_progress'?'selected':''?>>In progress</option><option value="resolved" <?=$r['status']==='resolved'?'selected':''?>>Resolved</option><option value="closed" <?=$r['status']==='closed'?'selected':''?>>Closed</option></select><label style="margin-top:8px">Admin note</label><textarea name="admin_note" style="width:100%;min-height:80px"><?=e($r['admin_note']??'')?></textarea><button class="mini-btn" type="submit">Save</button></form><form method="post" onsubmit="return confirm('Delete this request?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="mini-btn danger" type="submit">Delete</button></form></details></td></tr><?php endforeach; ?></tbody></table></div></div></section><?php require '../includes/footer.php'; ?>
